    join public.outing_music_positions omp on omp.id=oma.music_position_id
    where oma.id::text like 'c0160036-%'
      and oma.band_entity_id='7fafdc04-cb94-47d8-814f-5537639660ff'
      and omp.step_entity_id='c0160036-0716-4000-8000-000000000016'
  ) then raise exception 'ecija_alvarez_canonical_not_used'; end if;

  if (select count(*) from public.music_accompaniment_periods
      where id::text like 'c0160036-%'
        and year_from=2026 and year_to=2026 and is_current=false) <> 27
  then raise exception 'ecija_music_period_vigency_mismatch'; end if;

  if exists (
    select 1 from public.sources
    where url='https://www.bandademusicavillademarchena.es/inicio'
      and id::text like 'c0160036-%'
      and id<>'c0160036-0124-4000-8000-000000000024'
  ) then raise exception 'ecija_duplicate_f41_source'; end if;
end $$;

select
  'PREFLIGHT_ECIJA_SQL_OK_ROLLED_BACK' as result,
  776 as logical_dml,
  96 as new_entities,
  16 as outings,
  227 as source_links,
  32 as music_positions,
  28 as music_assignments;

rollback;
